steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        project(name: \"Mobile Redesign\") {
          id
          name
          documents {
            id
            title
            updatedAt
            lastEditor {
              id
              name
            }
          }
        }
        users {
          nodes {
            id
            name
            email
          }
        }
      }
    '
  }'
